<script setup lang="ts">
import { VueDraggable } from 'vue-draggable-plus'; import BlockRenderer from './BlockRenderer.vue'; import type { Block } from '../types';
const props=defineProps<{block:Block;labels:Record<string,string>;selectedId?:string;disabled?:boolean}>(); const emit=defineEmits<{select:[Block];remove:[string];changed:[]}>();
</script>
<template><div class="editable" :class="{picked:selectedId===block.id}" :style="{'--cols':String(block.props.columns||1)}" @click.stop="emit('select',block)"><span class="tag">⠿ {{labels[block.type]}} <em v-if="['header','footer'].includes(block.type)">锁定</em><button v-else-if="!disabled" @click.stop="emit('remove',block.id)">×</button></span><template v-if="block.type==='grid'"><div class="nested-title">{{block.props.title}} · {{block.props.columns||1}} 列</div><VueDraggable v-model="block.children" group="blocks" item-key="id" class="nested-drop" :disabled="disabled" :force-fallback="true" :fallback-on-body="true" @end="emit('changed')"><EditorBlock v-for="x in block.children" :key="x.id" :block="x" :labels="labels" :selected-id="selectedId" :disabled="disabled" @select="emit('select',$event)" @remove="block.children=block.children.filter(i=>i.id!==$event);emit('changed')" @changed="emit('changed')"/></VueDraggable></template><BlockRenderer v-else :block="block"/></div></template>
